arguments.command:
python3 - <<'EOF'
import pycdlib, io
iso=pycdlib.PyCdlib(); iso.open('/app/alpine.iso')
def cat(path):
    for use in ['iso_path','rr_path','joliet_path']:
        try:
            out=io.BytesIO(); iso.get_file_from_iso_fp(out, **{use:path}); return out.getvalue().decode(errors='replace')
        except Exception: pass
    return None
def walk(d='/'):
    try: kids=iso.list_children(iso_path=d)
    except Exception: return
    for c in kids:
        n=c.file_identifier().decode() if isinstance(c.file_identifier(),bytes) else c.file_identifier()
        if n in ('.','..'): continue
        p=(d.rstrip('/')+'/'+n)
        print(p)
        if c.is_dir(): 
            if d.count('/')<3: walk(p)
walk('/')
EOF

