arguments.command:
cd /app; cat > /app/step.py <<'EOF'
import socket,time,sys
s=socket.create_connection(('127.0.0.1',4444)); s.settimeout(2)
log=open('/app/session.log','ab')
def read(t):
    end=time.time()+t; out=b''
    while time.time()<end:
        try:
            d=s.recv(4096)
            if d: out+=d; log.write(d); log.flush()
        except socket.timeout: pass
    return out.decode(errors='replace')
def send(c,t=4):
    s.sendall(c.encode()+b'\n'); return read(t)
cmds=sys.argv[1:] if len(sys.argv)>1 else []
for c in cmds:
    if c.startswith('WAIT'):
        print(read(int(c[4:] or 5)))
    else:
        print('>>>',c); print(send(c))
EOF
python3 /app/step.py "ip -o link" "cat /etc/apk/repositories" "ls /media" "which sshd; apk info -e openssh"

